Add bounded retries around the read-only `GET`. Retry timeouts/transport errors, `429`, and `503`; honor `Retry-After`; do not retry other `4xx` or touch billing.

```python
import time
import httpx

RETRYABLE_STATUS = {429, 503}


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def __init__(
        self,
        *,
        timeout: float = 2.0,
        max_retries: int = 3,
        backoff: float = 0.5,
        max_retry_after: float = 30.0,
    ):
        self.timeout = timeout
        self.max_retries = max_retries
        self.backoff = backoff
        self.max_retry_after = max_retry_after

    def _retry_delay(self, attempt: int, response: httpx.Response | None = None) -> float:
        if response is not None:
            retry_after = response.headers.get("Retry-After")
            if retry_after:
                try:
                    return min(float(retry_after), self.max_retry_after)
                except ValueError:
                    pass  # HTTP-date Retry-After: fall back to backoff
        return min(self.backoff * (2 ** attempt), self.max_retry_after)

    def hourly(self, lat: float, lon: float) -> dict:
        for attempt in range(self.max_retries + 1):
            try:
                r = httpx.get(
                    f"{BASE}/hourly",
                    params={"lat": lat, "lon": lon},
                    timeout=self.timeout,
                )
            except (httpx.TimeoutException, httpx.TransportError):
                if attempt == self.max_retries:
                    raise
                time.sleep(self._retry_delay(attempt))
                continue

            if r.status_code in RETRYABLE_STATUS:
                if attempt == self.max_retries:
                    r.raise_for_status()
                time.sleep(self._retry_delay(attempt, r))
                continue

            r.raise_for_status()
            return r.json()
```

Notes:
- `GET` is safe to retry; do not copy this blindly to non-idempotent calls.
- The cap (`max_retry_after=30`) matches the provider’s “usually under 30 s” 503 guidance and prevents a huge `Retry-After` from blocking a request indefinitely.
- Add jitter if many clients share a key, and tests for: timeout then success, `429` with `Retry-After`, `503` then success, and non-retryable `400`/`404`.
- `billing/charge.py` uses a different client and should remain unchanged.

