```ts
// src/notifications/quietHours.ts
export function msUntilAllowed(tz: string, now = new Date()) {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: tz, hour12: false,
    hour: "2-digit", minute: "2-digit", second: "2-digit",
  }).formatToParts(now);
  const n = (t: string) => Number(parts.find(p => p.type === t)!.value);
  const sec = n("hour") * 3600 + n("minute") * 60 + n("second");
  if (sec >= 8 * 3600 && sec < 21 * 3600) return 0;
  return ((sec < 8 * 3600 ? 8 * 3600 - sec : 24 * 3600 - sec + 8 * 3600) * 1000);
}
```

