```python
# forecast/client.py
import random
import time

import httpx

BASE = "https://provider.example"  # unchanged

RETRY_STATUSES = {429, 500, 502, 503, 504}
MAX_ATTEMPTS = 5
MAX_DELAY = 30.0


def _retry_after_seconds(response: httpx.Response) -> float | None:
    value = response.headers.get("Retry-After")
    if value is None:
        return None
    try:
        return max(0.0, float(value))
    except ValueError:
        return None


def _backoff(attempt: int) -> float:
    # 0.5s, 1s, 2s, 4s ... plus jitter
    return min(MAX_DELAY, 0.5 * (2 ** attempt)) + random.uniform(0, 0.25)


def _get_with_retries(url: str, *, params: dict) -> httpx.Response:
    last_error: Exception | None = None

    for attempt in range(MAX_ATTEMPTS):
        try:
            response = httpx.get(
                url,
                params=params,
                timeout=httpx.Timeout(5.0, connect=3.0),
            )

            if response.status_code not in RETRY_STATUSES:
                response.raise_for_status()
                return response

            if attempt == MAX_ATTEMPTS - 1:
                response.raise_for_status()

            delay = _retry_after_seconds(response)
            if delay is None:
                delay = _backoff(attempt)
            time.sleep(delay)

        except httpx.TransportError as exc:
            # Includes timeouts, connection errors, etc.
            last_error = exc
            if attempt == MAX_ATTEMPTS - 1:
                raise
            time.sleep(_backoff(attempt))

    # Defensive fallback; normally unreachable.
    raise last_error or RuntimeError("request failed after retries")


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def hourly(self, lat: float, lon: float) -> dict:
        response = _get_with_retries(
            f"{BASE}/hourly",
            params={"lat": lat, "lon": lon},
        )
        return response.json()
```

Notes:
- Retries only safe, idempotent `GET` requests.
- Honors `Retry-After` for `429`; also retries transient `5xx`.
- Retries timeouts/connection errors with capped exponential backoff and jitter.
- Do **not** apply this blanket retry policy to `billing/charge.py`; payment POSTs need idempotency keys and their own policy.

```python
# forecast/client.py
import random
import time

import httpx

MAX_ATTEMPTS = 4
BACKOFF_BASE = 0.5
BACKOFF_MAX = 8.0
RETRY_STATUS = {429, 503}  # rate limit / deploy


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def _retry_delay(self, attempt: int, response: httpx.Response | None = None) -> float:
        if response is not None:
            retry_after = response.headers.get("Retry-After")
            if retry_after:
                try:
                    return max(0.0, float(retry_after))
                except ValueError:
                    pass  # fall back to backoff

        backoff = min(BACKOFF_MAX, BACKOFF_BASE * (2 ** attempt))
        return backoff * random.uniform(0.5, 1.0)  # jitter

    def hourly(self, lat: float, lon: float) -> dict:
        for attempt in range(MAX_ATTEMPTS):
            try:
                r = httpx.get(
                    f"{BASE}/hourly",
                    params={"lat": lat, "lon": lon},
                    timeout=2.0,
                )
            except httpx.TransportError:
                # Timeouts, connection errors, etc.
                if attempt == MAX_ATTEMPTS - 1:
                    raise
                time.sleep(self._retry_delay(attempt))
                continue

            if r.status_code in RETRY_STATUS and attempt < MAX_ATTEMPTS - 1:
                delay = self._retry_delay(attempt, r)
                r.close()
                time.sleep(delay)
                continue

            r.raise_for_status()
            return r.json()

        raise RuntimeError("unreachable")
```

Notes:
- Retries only idempotent GET requests.
- Retries transport/timeouts, `429`, and `503`.
- Honors `Retry-After` for `429`; otherwise uses capped exponential backoff with jitter.
- Does not retry other 4xx errors.
- Billing/Stripe code is untouched.

Add a bounded retry helper and make the handler idempotent, because the provider may redeliver events.

```python
import random
import time
from fastapi import HTTPException

MAX_ATTEMPTS = 3
BASE_DELAY = 0.2          # seconds
MAX_RETRY_WINDOW = 3.5    # stay under provider's 5s timeout

def create_shipment_with_retry(order):
    started = time.monotonic()

    for attempt in range(MAX_ATTEMPTS):
        try:
            return fulfillment.create_shipment(
                order,
                idempotency_key=f"shipment:{order.id}",
            )
        except Exception:
            elapsed = time.monotonic() - started
            if attempt == MAX_ATTEMPTS - 1 or elapsed >= MAX_RETRY_WINDOW:
                raise

            delay = min(
                BASE_DELAY * (2 ** attempt) + random.uniform(0, 0.1),
                MAX_RETRY_WINDOW - elapsed,
            )
            time.sleep(max(0, delay))


@app.post("/webhooks/payments")
def payment_succeeded(event: PaymentEvent):
    order = Order.get(event.order_id)

    if not order.paid:
        order.mark_paid()
        order.save()

    if not order.shipment_created:
        try:
            create_shipment_with_retry(order)
        except Exception:
            # Let the provider redeliver; idempotency prevents duplicate side effects.
            raise HTTPException(status_code=503, detail="Fulfillment unavailable")

        order.shipment_created = True
        order.save()

    return {"ok": True}
```

Key points:

- Retries use exponential backoff with jitter.
- The retry window is capped so the webhook stays within the provider’s 5-second limit.
- `idempotency_key` and the `shipment_created` check prevent duplicate shipments on redelivery.
- If fulfillment still fails, return a non-2xx so the provider retries later.
- Also configure the fulfillment client’s per-request timeout (e.g. ~1s); otherwise one hanging call can still exceed 5s. If fulfillment can be slow, move this to a queue/worker instead of retrying inline.

