```ts
export function localHour(tz: string, at = new Date()) {
  return Number(new Intl.DateTimeFormat("en-GB",
    { timeZone: tz, hour: "2-digit", hour12: false }).format(at));
}
export function msUntilWindow(tz: string) {   // 0 if inside 08:00–21:00
  const h = localHour(tz);
  if (h >= 8 && h < 21) return 0;
  // minutes to next 08:00 local
  const now = new Date();
  const mins = ((8 - h + 24) % 24) * 60 - now.getUTCMinutes();
  return mins * 60_000;
}
```

