Add bounded retries for transient failures only. Keep billing/payment code untouched.

```python
# forecast/client.py
import random
import time

import httpx

BASE = "..."  # existing


class ForecastClient:
    def __init__(
        self,
        max_attempts: int = 4,
        base_delay: float = 0.5,
        max_delay: float = 8.0,
    ):
        self.max_attempts = max_attempts
        self.base_delay = base_delay
        self.max_delay = max_delay

    def hourly(self, lat: float, lon: float) -> dict:
        last_exc = None

        for attempt in range(1, self.max_attempts + 1):
            try:
                r = httpx.get(
                    f"{BASE}/hourly",
                    params={"lat": lat, "lon": lon},
                    timeout=2.0,
                )

                if r.status_code == 429:
                    if attempt == self.max_attempts:
                        r.raise_for_status()
                    time.sleep(self._retry_after(r) or self._backoff(attempt))
                    continue

                if r.status_code == 503:
                    if attempt == self.max_attempts:
                        r.raise_for_status()
                    time.sleep(self._backoff(attempt))
                    continue

                r.raise_for_status()
                return r.json()

            except httpx.TransportError as exc:
                # Timeouts, connect/read/write/pool errors.
                last_exc = exc
                if attempt == self.max_attempts:
                    raise
                time.sleep(self._backoff(attempt))

        raise last_exc  # unreachable

    @staticmethod
    def _retry_after(response: httpx.Response) -> float | None:
        raw = response.headers.get("Retry-After")
        if raw is None:
            return None
        try:
            return max(0.0, float(raw))
        except ValueError:
            return None

    def _backoff(self, attempt: int) -> float:
        cap = min(self.max_delay, self.base_delay * (2 ** (attempt - 1)))
        return random.uniform(cap * 0.5, cap)
```

Behavior:
- Retries `httpx.TransportError` — including timeouts and connection errors.
- Retries `429`, respecting `Retry-After` when present.
- Retries `503` during deploys with exponential backoff and jitter.
- Fails fast on other 4xx, JSON decode errors, etc.
- Bounds retries so callers do not hang indefinitely.
- Does not affect `billing/charge.py`.

Suggested tests: timeout then success, repeated timeout exhausts, `429` honors `Retry-After`, `503` retries, `400` does not retry, and final exception propagates.

