```python
import random
import time
import httpx

BASE = "..."
RETRY_STATUS = frozenset({429, 500, 502, 503, 504})
MAX_ATTEMPTS = 4
MAX_RETRY_AFTER = 30.0  # docs: 503s clear in <30 s


def _backoff(attempt: int) -> float:
    base = min(8.0, 0.5 * 2 ** (attempt - 1))
    return base * random.uniform(0.5, 1.0)  # jitter: avoid sync'd retries


def _retry_after(value: str | None) -> float | None:
    if not value:
        return None
    try:
        return min(float(value), MAX_RETRY_AFTER)
    except ValueError:
        return None  # HTTP-date form: fall back to our backoff


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def __init__(self):
        self._http = httpx.Client(
            base_url=BASE, timeout=httpx.Timeout(2.0, connect=1.0)
        )

    def hourly(self, lat: float, lon: float) -> dict:
        return self._get("/hourly", params={"lat": lat, "lon": lon})

    def _get(self, path: str, params: dict | None = None) -> dict:
        for attempt in range(1, MAX_ATTEMPTS + 1):
            wait = None
            try:
                r = self._http.get(path, params=params)
            except (httpx.TimeoutException, httpx.TransportError):
                if attempt == MAX_ATTEMPTS:
                    raise
            else:
                if r.status_code not in RETRY_STATUS:
                    r.raise_for_status()  # 400/401/404 etc.: retrying won't help
                    return r.json()
                if attempt == MAX_ATTEMPTS:
                    r.raise_for_status()
                wait = _retry_after(r.headers.get("Retry-After"))
            time.sleep(wait if wait is not None else _backoff(attempt))
        raise AssertionError("unreachable")
```

Why this shape:

- **Retries timeouts/transport errors and 429/5xx only** — not 4xx, which are permanent.
- **Honors `Retry-After`** on 429, and surfaces a 429 that asks for >30 s rather than sleeping blindly.
- **Bounded**: 4 attempts, capped/jittered backoff, so a request can't hang forever.
- **Reuses one `httpx.Client`** (connection pooling) instead of a module-level `httpx.get`.
- Rate limit is a non-issue: worst case 4 requests per call, far under 600/min.

Also worth adding a metric/log line per retry so timeout rates stay visible.

## Recommendation

`hourly()` is a read-only GET, so retrying is safe (idempotent). The provider docs tell us exactly what to retry on: **429** (honor `Retry-After`) and **503** (short deploy blips). Timeouts/connect errors should also be retried. Other 4xx (401/404) should fail fast — retrying won't help.

Note: `httpx.HTTPTransport(retries=N)` only retries connection failures, not 429/503, so use an explicit loop. Don't touch `billing/charge.py` — it's a separate Stripe client with different semantics (charging is *not* idempotent, retries there need keys).

```python
import random
import time
import httpx

BASE = "https://api.example.com"
MAX_ATTEMPTS = 4
BASE_DELAY = 0.5   # seconds
MAX_DELAY = 8.0

RETRY_STATUS = {429, 503}


def _retry_delay(attempt: int, retry_after: str | None) -> float:
    if retry_after:
        try:
            return min(float(retry_after), 30.0)  # docs: 503 usually < 30 s
        except ValueError:
            pass
    # exponential backoff + jitter, to avoid thundering herd
    return min(BASE_DELAY * 2 ** attempt, MAX_DELAY) * random.uniform(0.5, 1.0)


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def hourly(self, lat: float, lon: float) -> dict:
        last_exc: Exception | None = None

        for attempt in range(MAX_ATTEMPTS):
            try:
                r = httpx.get(
                    f"{BASE}/hourly",
                    params={"lat": lat, "lon": lon},
                    timeout=2.0,
                )
                if r.status_code in RETRY_STATUS and attempt < MAX_ATTEMPTS - 1:
                    time.sleep(_retry_delay(attempt, r.headers.get("Retry-After")))
                    continue
                r.raise_for_status()
                return r.json()

            except (httpx.TimeoutException, httpx.ConnectError) as e:
                last_exc = e
                if attempt == MAX_ATTEMPTS - 1:
                    raise
                time.sleep(_retry_delay(attempt, None))

        raise last_exc  # unreachable, kept for type checkers
```

**Notes**
- Worst case latency: 4 × 2 s timeout + backoff ≈ 10–12 s. Tune `MAX_ATTEMPTS` if callers have tighter deadlines.
- 600 req/min is generous; backoff+jitter keeps retries well inside the limit.
- Consider making `MAX_ATTEMPTS`/`BASE` injectable for tests, and log each retry with the status code so you can confirm 503s are the real cause.

