function delayUntilSendable(now: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone, hour: "2-digit", minute: "2-digit", hourCycle: "h23",
  }).formatToParts(now);
  const hour = Number(parts.find(p => p.type === "hour")!.value);
  const minute = Number(parts.find(p => p.type === "minute")!.value);

  if (hour >= 8 && hour < 21) return 0;

  // For <08:00 send today at 08:00; for >=21:00 send tomorrow at 08:00.
  const mins = hour < 8 ? (8 * 60 - (hour * 60 + minute))
                        : (24 * 60 - (hour * 60 + minute) + 8 * 60);
  return mins * 60_000;
}
```
This uses the buyer’s `timezone`; UK/IE buyers get their own local 08:00.

