Update `forecast/client.py` to retry safe GET requests on transport/timeout errors, `429`, and `503`. Honor `Retry-After` when present, otherwise use jittered exponential backoff. Keep `billing/charge.py` untouched.

```python
import random
import time

import httpx

BASE = "..."  # unchanged


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    MAX_ATTEMPTS = 4
    BASE_DELAY = 0.25
    MAX_DELAY = 8.0

    def hourly(self, lat: float, lon: float) -> dict:
        return self._get_with_retries(
            f"{BASE}/hourly",
            params={"lat": lat, "lon": lon},
        )

    def _get_with_retries(self, url: str, params: dict) -> dict:
        last_exc: Exception | None = None

        for attempt in range(1, self.MAX_ATTEMPTS + 1):
            try:
                r = httpx.get(url, params=params, timeout=2.0)

                if r.status_code == 429:
                    if attempt == self.MAX_ATTEMPTS:
                        r.raise_for_status()
                    time.sleep(self._retry_after(r, attempt))
                    continue

                if r.status_code == 503:
                    if attempt == self.MAX_ATTEMPTS:
                        r.raise_for_status()
                    time.sleep(self._backoff(attempt))
                    continue

                r.raise_for_status()
                return r.json()

            except httpx.TransportError as exc:
                # Includes timeouts and connection failures.
                last_exc = exc
                if attempt == self.MAX_ATTEMPTS:
                    raise
                time.sleep(self._backoff(attempt))

        raise last_exc if last_exc else RuntimeError("retry loop exited")

    def _backoff(self, attempt: int) -> float:
        delay = min(self.MAX_DELAY, self.BASE_DELAY * (2 ** (attempt - 1)))
        return random.uniform(0, delay)

    def _retry_after(self, r: httpx.Response, attempt: int) -> float:
        header = r.headers.get("Retry-After")
        if header:
            try:
                return min(float(header), self.MAX_DELAY)
            except ValueError:
                pass
        return self._backoff(attempt)
```

This retries only transient failures, bounds total attempts, avoids retrying ordinary 4xx errors, and respects provider `429` guidance.

