```python
import random
import time

import httpx

REQUEST_TIMEOUT = 2.0
MAX_ATTEMPTS = 4
BACKOFF = 0.5
MAX_BACKOFF = 8.0
TOTAL_BUDGET = 25.0
RETRY_STATUSES = {429, 500, 502, 503, 504}


def _retry_after_seconds(response: httpx.Response) -> float | None:
    raw = response.headers.get("Retry-After")
    if raw is None:
        return None
    try:
        return max(0.0, float(raw))
    except ValueError:
        return None


def _delay(response: httpx.Response | None, attempt: int) -> float:
    retry_after = _retry_after_seconds(response) if response else None
    if retry_after is not None:
        return retry_after
    return min(BACKOFF * (2 ** attempt), MAX_BACKOFF) + random.uniform(0, 0.25)


class ForecastClient:
    """Fetches hourly forecasts; read-only GET requests."""

    def hourly(self, lat: float, lon: float) -> dict:
        deadline = time.monotonic() + TOTAL_BUDGET
        last_exc: Exception | None = None

        for attempt in range(MAX_ATTEMPTS):
            response = None
            try:
                response = httpx.get(
                    f"{BASE}/hourly",
                    params={"lat": lat, "lon": lon},
                    timeout=REQUEST_TIMEOUT,
                )
            except httpx.TransportError as exc:  # timeouts, connection errors
                last_exc = exc
            else:
                if response.status_code not in RETRY_STATUSES:
                    response.raise_for_status()
                    return response.json()

            delay = _delay(response, attempt)
            if attempt == MAX_ATTEMPTS - 1 or time.monotonic() + delay >= deadline:
                if response is not None:
                    response.raise_for_status()
                raise last_exc  # type: ignore[misc]

            time.sleep(delay)

        raise last_exc  # type: ignore[misc]
```

Notes:
- Retries timeouts/transport errors, `429`, and transient `5xx`.
- Honors `Retry-After`; otherwise exponential backoff with jitter.
- Does not retry ordinary `4xx`; `raise_for_status()` still surfaces them.
- Stops before exceeding the overall budget instead of sleeping indefinitely.
- Tests to add: timeout then success, `503` then success, `429` with `Retry-After`, `400` not retried, and exhaustion raises.

